class Playground{
    constructor(){
        this.simulation = new Simulation();
        this.mousePos = this.simulation.bottle.center.Cpy();
        this.lastMousePos = this.mousePos.Cpy();
        this.keys = new Set();

        this.pouring = false;
        this.REST_ANGLE = Math.PI / 2;     // upright, mouth up
        this.ROT_SPEED = 1.9;              // rad/s manual tipping speed
        this.MIN_ANGLE = -1.05;            // tipped hard to the left (pour)
        this.MAX_ANGLE = 2.6;              // tipped hard to the right
        this.targetAngle = this.REST_ANGLE;
        this.angle = this.REST_ANGLE;
    }

    update(dt){
        let frameDt = Math.min(dt, 0.033);

        // Carry the bottle toward the cursor with a bit of weight.
        let posEase = 1 - Math.pow(0.0006, frameDt);
        let center = this.simulation.bottle.center;
        this.simulation.bottle.center = Add(center, Scale(Sub(this.mousePos, center), posEase));

        // Q tips the bottle one way, W the other (arrows too). The tilt is held.
        let rot = 0;
        if(this.keys.has("q") || this.keys.has("arrowleft")){ rot -= 1; }
        if(this.keys.has("w") || this.keys.has("arrowright")){ rot += 1; }
        if(this.pouring){ rot -= 1; }   // holding the mouse pours like Q

        this.targetAngle += rot * this.ROT_SPEED * frameDt;
        this.targetAngle = Math.max(this.MIN_ANGLE, Math.min(this.MAX_ANGLE, this.targetAngle));

        // Smoothly ease the bottle toward the target tilt -> weighty, controllable pour.
        let ease = 1 - Math.pow(0.0009, frameDt);
        this.angle += (this.targetAngle - this.angle) * ease;
        this.simulation.setBottleAngle(this.angle);

        this.simulation.updateGlassTilt(frameDt);

        for(let i=0; i<4; i++){
            this.simulation.update(frameDt * 1.85);
        }
    }

    /* render delegates (called from Main.html) */
    drawBack(){ this.simulation.drawBack(); }
    drawFront(){ this.simulation.drawFront(); }
    drawBeer(targetCtx){ this.simulation.drawBeer(targetCtx); }
    drawFoam(targetCtx){ this.simulation.drawFoam(targetCtx); }
    drawBeerDetails(targetCtx){ this.simulation.drawBeerDetails(targetCtx); }
    drawFoamDetails(targetCtx){ this.simulation.drawFoamDetails(targetCtx); }

    setPourAmount(value){
        this.simulation.setPourAmount(value);
    }

    onMouseMove(position){
        this.lastMousePos = this.mousePos.Cpy();
        // keep the bottle on-screen and above the table; update() eases toward this
        let x = Math.max(140, Math.min(canvas.width - 60, position.x));
        let y = Math.max(120, Math.min(440, position.y));
        this.mousePos = new Vector2(x, y);
    }

    onMouseDown(button){
        if(button === 0){
            this.pouring = true;
        }
    }

    onMouseUp(button){
        if(button === 0){
            this.pouring = false;
        }
    }

    // used by the headless screenshot harness
    setHold(value){
        this.pouring = !!value;
    }

    onKeyDown(key){
        this.keys.add(key.toLowerCase());
    }

    onKeyUp(key){
        this.keys.delete(key.toLowerCase());
    }
}

