    worldBoundary(){
        let tableY = this.glass.center.y + this.glass.height * 0.5 + 2;
        for(let i=0; i< this.particles.length; i++){
            let p = this.particles[i];
            let pos = p.position;

            if(pos.x < 0){
                pos.x = 0;
                p.prevPosition.x = 0;
            }
            if(pos.y < 0){
                pos.y = 0;
                p.prevPosition.y = 0;
            }
            if(pos.x > canvas.width){
                pos.x = canvas.width-1;
                p.prevPosition.x = canvas.width-1;
            }
            // Spilled beer pools on the table the glass stands on, not the screen edge.
            if(pos.y > tableY && !this.isInsideGlassInterior(pos)){
                pos.y = tableY;
                p.prevPosition.y = tableY;
            }
            if(pos.y > canvas.height){
                pos.y = canvas.height-1;
                p.prevPosition.y = canvas.height-1;
            }
        }
    }

    trimParticles(){
        // Drop particles that have spilled off the table so they don't pile up forever.
        for(let i=this.particles.length - 1; i>=0; i--){
            let p = this.particles[i];
            if(p.position.y > canvas.height - 4 && !this.isInsideGlassInterior(p.position)){
                p.deadTimer = (p.deadTimer || 0) + 1;
                if(p.deadTimer > 90){
                    this.particles.splice(i, 1);
                }
            }
        }
        if(this.particles.length > this.MAX_PARTICLES){
            this.particles.splice(0, this.particles.length - this.MAX_PARTICLES);
