            let coverSurface = Math.max(0, Math.min(1, 1 - p.cover / this.SURFACE_COVER));
            let headSurface = 0;
            let belowHead = 0;
            if(inGlass){
                let local = this.worldToGlassLocal(p.position);
                let surfaceY = this.getGlassSurfaceLocalY();
                belowHead = Math.max(0, local.y - surfaceY);
                headSurface = Math.max(0, Math.min(1, 1 - belowHead / 78));
            }
            p.surface = inGlass ? headSurface : coverSurface;

