    diffuseFoam(dt){
        let ps = this.particles;
        let nbr = this.nbrIdx;
        let start = this.nbrStart;
        let R = this.INTERACTION_RADIUS;
        let R2 = R * R;
        let invR = 1 / R;
        let rate = 0.18 * dt;

        for(let i=0; i<ps.length; i++){
            let pa = ps[i];
            if(pa.foam <= 0.02 && pa.surface <= 0.08){
                continue;
            }

            let s = start[i];
            let e = start[i + 1];
            for(let k=s; k<e; k++){
                let j = nbr[k];
                if(j < i){
                    continue;
                }

                let pb = ps[j];
                let rx = pb.position.x - pa.position.x;
                let ry = pb.position.y - pa.position.y;
                let d2 = rx * rx + ry * ry;
                if(d2 >= R2){
