    createFoamBurst(position, intensity){
        let amount = Math.max(1, Math.floor(1 + intensity * 2.5));
        for(let i=0; i<amount && this.foamParticles.length < this.MAX_FOAM_PARTICLES; i++){
            let angle = Math.random() * Math.PI * 2;
            let radius = Math.random() * 8 * intensity;
            let pos = Add(position, new Vector2(Math.cos(angle) * radius, Math.sin(angle) * radius));
            let vel = new Vector2(
                (Math.random() - 0.5) * (9 + intensity * 7),
                -6 - Math.random() * (8 + intensity * 8)
            );
            let bubbleRadius = 3 + Math.random() * 4 + intensity * 2;
            let life = 0.5 + Math.random() * 0.6 + intensity * 0.4;
            this.foamParticles.push(new FoamParticle(pos, vel, bubbleRadius, life));
        }
    }

    // Airborne splash flecks thrown up by a hard pour; they arc up and fall back.
    updateFoamParticles(dt){
        for(let i=this.foamParticles.length - 1; i>=0; i--){
            let foam = this.foamParticles[i];
            foam.life -= dt * 0.14;

            if(foam.life <= 0){
                this.foamParticles.splice(i, 1);
                continue;
            }

            foam.prevPosition = foam.position.Cpy();
            foam.velocity.y += 1.7 * dt;
            foam.velocity.x += Math.sin(foam.seed + foam.life * 7.0) * 0.05;
            foam.velocity = Scale(foam.velocity, 0.985);
            foam.position = Add(foam.position, Scale(foam.velocity, dt));

            for(let j=0; j<this.shapes.length; j++){
                let dir = this.shapes[j].getDirectionOut(foam.position);
                if(dir != null){
                    foam.position = Add(foam.position, dir);
                    foam.velocity = Scale(foam.velocity, 0.5);
                }
            }

            if(foam.position.x < -20 || foam.position.x > canvas.width + 20 || foam.position.y > canvas.height + 40){
                this.foamParticles.splice(i, 1);
            }
        }
    }

